import{_ as l,l as s,o as e,c as i,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"采样与草图统计","description":"","frontmatter":{"title":"采样与草图统计","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-sampling-sketches.md","filePath":"cs/db-sampling-sketches.md","lastUpdated":1789023840000}'),h={name:"cs/db-sampling-sketches.md"};function E(A,a,m,_,B,T){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="采样与草图统计" tabindex="-1">采样与草图统计 <a class="header-anchor" href="#采样与草图统计" aria-label="Permalink to &quot;采样与草图统计&quot;">​</a></h1><div class="epigraph"><p>目录里的直方图会过期；采样与草图用可控误差再看一眼数据，给优化器另一份基数输入。</p><footer>—— 据 Olken and Rotem 对数据库采样；Haas et al.；HyperLogLog 在 NDV；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/cardinality-error-propagation">上一课</a>指出独立假设连乘会炸。本课不重推误差公式。缺口是统计怎么来：全表扫描维护精确 NDV 太贵；过期 ANALYZE 比错误公式更常见。采样（行样本、块样本）与草图（概率结构）在精度、CPU、存储之间折中。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>COUNT(DISTINCT)</code> 与连接 NDV 需要不同值个数。精确维护每个列每个组合不可能。缺口是估计器：均匀行采样在聚簇数据上偏倚；块采样便宜但方差大。草图：HyperLogLog 估 NDV，Count-Min 估频率，quantile sketch 估分位以建直方图。这些结构在计算机课已作为数据流出现；本课只把它们接到优化器目录。</p><p>动态采样：优化时扫一小份数据估当前谓词选择率，适合参数化查询与过期统计。代价是优化时间变长——与计划缓存的「跳过优化」相反。</p><p><span class="marginnote">Olken 的数据库采样综述。HLL 见 Flajolet et al.。本课不把草图当查询结果（近似查询另册），只当优化器输入。计算机栏的 HyperLogLog 课已有算法，这里不重推散列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ANALYZE：按块或行取样，建直方图、最频繁值、NULL 比例、NDV 草图。多列：对查询里常见列组维护联合统计或列组 NDV。动态采样：对单次查询的谓词在表上抽若干块。</p><p>样本大小决定置信：选择率极低的谓词（「选一个主键」）样本里可能零命中，要用平滑或改走索引统计。这是估计器偏差，不是存储 bug。</p>',10)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%9F%BA%E8%A1%A8%22%5D%20--%3E%20SMP%5B%22%E8%A1%8C%20%2F%20%E5%9D%97%E9%87%87%E6%A0%B7%22%5D%0A%20%20T%20--%3E%20SK%5B%22NDV%20%2F%20%E9%A2%91%E7%8E%87%E8%8D%89%E5%9B%BE%22%5D%0A%20%20SMP%20--%3E%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E6%A1%B6%22%5D%0A%20%20SK%20--%3E%20CAT%5B%22%E7%9B%AE%E5%BD%95%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20HIST%20--%3E%20CAT%0A%20%20CAT%20--%3E%20OPT%5B%22%E4%BB%A3%E4%BB%B7%E4%B8%8E%20DP%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>统计是快照：写入一秒钟后样本过期。自动 ANALYZE 阈值（表改了百分之几）是工程。锁定计划的预编译语句在统计刷新后应失效——<a href="/cs/prepared-plan-cache">计划缓存</a> 已要求。</p><p>草图有可合并性：分区表各分区一份 HLL，可并成全表 NDV，服务后课分区裁剪与全局估计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准代价公式里的随机 I/O 常数——下一课代价模型校准。也不把采样查询（<code>TABLESAMPLE</code>）的用户语义与优化器内部采样混成同一 API。近似聚合查询是分析课，不是优化器统计。</p><p>后课默认：统计来自样本与草图，带误差条；极低选择率不要信样本零命中。校准课把「模型常数」与「基数输入」分开调。</p><p>优化器读的是摘要，不是每次优化全表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>采样与草图维护 NDV、频率、直方图，误差可控但非零。</li><li>动态采样用优化时间换较新的选择率。</li><li>代价模型校准下一课：同样基数下，I/O 与 CPU 权重仍可能错。</li><li>出处：Olken and Rotem；Haas 等；Flajolet 等 HLL；Ramakrishnan and Gehrke。</li></ul>',9))])}const k=l(h,[["render",E]]);export{D as __pageData,k as default};
